using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DesignStore.Application.Commerce;
using DesignStore.Application.Abstractions.Files;
using DesignStore.Domain.Catalog;
using DesignStore.Domain.Commerce;
using DesignStore.Infrastructure.Persistence;
using FluentValidation;
using Microsoft.EntityFrameworkCore;

namespace DesignStore.Infrastructure.Commerce;

public sealed class InquiryQuoteService(ApplicationDbContext db, IFileStorageService storage) : IInquiryQuoteService
{
    static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
    static string Number(string prefix) => $"{prefix}-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(1000,9999)}";
    public async Task<ProductInquiry> CreateInquiryAsync(CreateInquiryRequest request, CancellationToken ct)
    {
        if (!request.TermsAccepted) throw new ValidationException("Pro pokračování je nutný souhlas s podmínkami.");
        if (request.Quantity is < 1 or > 99 || string.IsNullOrWhiteSpace(request.Email) || string.IsNullOrWhiteSpace(request.FullName)) throw new ValidationException("Neplatné údaje poptávky.");
        var product = await db.Products.Include(x=>x.Translations).Include(x=>x.Variants).ThenInclude(x=>x.Translations).FirstOrDefaultAsync(x=>x.Id==request.ProductId && x.IsPublished,ct) ?? throw new ValidationException("Produkt není dostupný.");
        var variant = request.ProductVariantId.HasValue ? product.Variants.FirstOrDefault(x=>x.Id==request.ProductVariantId) : null;
        if (product.HasVariants && variant is null) throw new ValidationException("Vyberte platnou variantu.");
        var made = variant is not null ? variant.AvailabilityStatus == AvailabilityStatus.MadeToOrder && variant.CanBeMadeToOrder : product.AvailabilityStatus == AvailabilityStatus.MadeToOrder && product.CanBeMadeToOrder;
        if (!made) throw new ValidationException("Tento produkt není dostupný pro poptávku výroby.");
        var inquiry = new ProductInquiry{Number=Number("INQ"),ProductId=product.Id,ProductVariantId=variant?.Id,Email=request.Email.Trim(),FullName=request.FullName.Trim(),CountryCode=request.CountryCode.Trim().ToUpperInvariant(),Quantity=request.Quantity,RequestedDeadline=request.RequestedDeadline?.Trim(),Note=request.Note?.Trim(),TermsAccepted=true,ProductName=product.Translations.FirstOrDefault(x=>x.Culture=="cs-CZ")?.Name??product.Sku,VariantName=variant?.Name??"",Sku=variant?.Sku??product.Sku,ImageUrl=product.MainImageUrl,CatalogPrice=variant?.Price??product.BasePrice,VatRate=product.VatRate,Currency="CZK",Status=InquiryStatus.New};
        inquiry.Configuration.AddRange(request.Configuration.Select(x=>new ProductInquiryConfigurationItem{OptionName=x.OptionName.Trim(),Value=x.Value.Trim(),PriceAdjustment=x.PriceAdjustment})); inquiry.StatusHistory.Add(new ProductInquiryStatusHistory{NewStatus=InquiryStatus.New,Reason="Poptávka vytvořena"}); db.ProductInquiries.Add(inquiry); await db.SaveChangesAsync(ct); return inquiry;
    }
    public async Task AddAttachmentAsync(Guid inquiryId, FileUpload upload, CancellationToken ct){var inquiry=await db.ProductInquiries.FirstOrDefaultAsync(x=>x.Id==inquiryId,ct)??throw new KeyNotFoundException();var stored=await storage.SaveAttachmentAsync(upload,ct);db.ProductInquiryAttachments.Add(new ProductInquiryAttachment{ProductInquiryId=inquiryId,StorageKey=stored.StorageKey,OriginalName=stored.OriginalName,ContentType=stored.ContentType,Length=stored.Length,Sha256=stored.Sha256,IsSafe=true});await db.SaveChangesAsync(ct);}
    public async Task<IReadOnlyList<InquirySummary>> GetInquiriesAsync(CancellationToken ct)=>await db.ProductInquiries.AsNoTracking().OrderByDescending(x=>x.CreatedAtUtc).Select(x=>new InquirySummary(x.Id,x.Number,x.Status,x.ProductName,x.Email,x.CreatedAtUtc)).Take(200).ToListAsync(ct);
    public async Task<Quote> CreateQuoteAsync(Guid inquiryId,IReadOnlyList<(string Description,int Quantity,decimal UnitPrice,decimal VatRate)> items,decimal deposit,DateTime validUntilUtc,string terms,CancellationToken ct){if(items.Count==0||validUntilUtc<=DateTime.UtcNow)throw new ValidationException("Nabídka musí mít položky a platnost v budoucnosti.");var inquiry=await db.ProductInquiries.Include(x=>x.Quotes).FirstOrDefaultAsync(x=>x.Id==inquiryId,ct)??throw new KeyNotFoundException();if(inquiry.Status is InquiryStatus.Rejected or InquiryStatus.Closed or InquiryStatus.ConvertedToOrder)throw new ValidationException("Poptávka již není aktivní.");var version=(inquiry.Quotes.Count==0?0:inquiry.Quotes.Max(x=>x.Version))+1;var quote=new Quote{Number=Number("QUO"),ProductInquiryId=inquiryId,Version=version,ValidUntilUtc=validUntilUtc,DepositAmount=deposit,Terms=terms.Trim(),Status=QuoteStatus.Draft};foreach(var i in items){if(i.Quantity<1||i.UnitPrice<0)throw new ValidationException("Neplatná položka nabídky.");quote.Items.Add(new QuoteItem{Description=i.Description.Trim(),Quantity=i.Quantity,UnitPrice=i.UnitPrice,VatRate=i.VatRate,LineTotal=i.UnitPrice*i.Quantity});}quote.Subtotal=quote.Items.Sum(x=>x.LineTotal);quote.TaxTotal=quote.Items.Sum(x=>Math.Round(x.LineTotal*x.VatRate/(100+x.VatRate),2));quote.Total=quote.Subtotal;inquiry.Status=InquiryStatus.InReview;db.Quotes.Add(quote);await db.SaveChangesAsync(ct);return quote;}
    public async Task<string> SendQuoteAsync(Guid quoteId,CancellationToken ct){var quote=await db.Quotes.Include(x=>x.ProductInquiry).Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==quoteId,ct)??throw new KeyNotFoundException();if(quote.Status!=QuoteStatus.Draft)throw new ValidationException("Odeslat lze pouze koncept nabídky.");var token=Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).Replace('+','-').Replace('/','_').TrimEnd('=');quote.Status=QuoteStatus.Sent;quote.ProductInquiry.Status=InquiryStatus.QuoteSent;quote.StatusHistory.Add(new QuoteStatusHistory{NewStatus=QuoteStatus.Sent,Reason="Nabídka odeslána"});quote.AccessTokens.Add(new QuoteAccessToken{TokenHash=Hash(token),ExpiresAtUtc=quote.ValidUntilUtc??DateTime.UtcNow.AddDays(14)});db.OutboxMessages.Add(new OutboxMessage{Type="QuoteSent",Payload=JsonSerializer.Serialize(new{quote.Number,quote.ProductInquiry.Email,quote.Id})});await db.SaveChangesAsync(ct);return token;}
    public async Task<QuoteView?> GetQuoteAsync(string token,CancellationToken ct){var q=await db.Quotes.AsNoTracking().Include(x=>x.Items).Include(x=>x.AccessTokens).FirstOrDefaultAsync(x=>x.AccessTokens.Any(t=>t.TokenHash==Hash(token)&&t.RevokedAtUtc==null),ct);if(q is null||q.ValidUntilUtc<=DateTime.UtcNow||q.Status is QuoteStatus.Expired or QuoteStatus.Cancelled)return null;return new(q.Id,q.Number,q.Version,q.Status,q.Subtotal,q.TaxTotal,q.DepositAmount,q.Total,q.Currency,q.ValidUntilUtc,q.Items.Select(x=>$"{x.Description} × {x.Quantity}: {x.LineTotal:N2}").ToList(),q.Status==QuoteStatus.Sent||q.Status==QuoteStatus.ChangeRequested);}
    public async Task RespondToQuoteAsync(string token,QuoteStatus response,string? comment,CancellationToken ct){if(response is not (QuoteStatus.Accepted or QuoteStatus.Rejected or QuoteStatus.ChangeRequested))throw new ValidationException("Neplatná odpověď na nabídku.");var q=await db.Quotes.Include(x=>x.ProductInquiry).Include(x=>x.AccessTokens).FirstOrDefaultAsync(x=>x.AccessTokens.Any(t=>t.TokenHash==Hash(token)),ct)??throw new KeyNotFoundException();if(q.ValidUntilUtc<=DateTime.UtcNow||q.Status!=QuoteStatus.Sent)throw new ValidationException("Nabídka již není platná.");q.Status=response;q.ProductInquiry.Status=response==QuoteStatus.Accepted?InquiryStatus.Accepted:response==QuoteStatus.Rejected?InquiryStatus.Rejected:InquiryStatus.InReview;q.StatusHistory.Add(new QuoteStatusHistory{PreviousStatus=QuoteStatus.Sent,NewStatus=response,Reason=comment??"Zákaznická odpověď"});await db.SaveChangesAsync(ct);}
    public async Task<Quote> ConvertQuoteToOrderAsync(string token,string idempotencyKey,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var q=await db.Quotes.Include(x=>x.ProductInquiry).Include(x=>x.Items).Include(x=>x.AccessTokens).FirstOrDefaultAsync(x=>x.AccessTokens.Any(t=>t.TokenHash==Hash(token)),ct)??throw new KeyNotFoundException();if(q.ConvertedOrderId.HasValue)return q;if(q.Status!=QuoteStatus.Accepted||q.ValidUntilUtc<=DateTime.UtcNow)throw new ValidationException("Nabídku lze převést pouze po přijetí a před expirací.");var order=new Order{Number=Number("WS"),IdempotencyKey=idempotencyKey,AccessTokenHash=Hash(idempotencyKey),Email=q.ProductInquiry.Email,Currency=q.Currency,Subtotal=q.Subtotal,TaxTotal=q.TaxTotal,Total=q.Total,Status=OrderStatus.PendingPayment};foreach(var i in q.Items)order.Items.Add(new OrderItem{ProductId=q.ProductInquiry.ProductId,ProductVariantId=q.ProductInquiry.ProductVariantId,ProductName=q.ProductInquiry.ProductName,VariantName=q.ProductInquiry.VariantName,Sku=q.ProductInquiry.Sku,ImageUrl=q.ProductInquiry.ImageUrl,Quantity=i.Quantity,UnitPrice=i.UnitPrice,VatRate=i.VatRate,TaxAmount=Math.Round(i.LineTotal*i.VatRate/(100+i.VatRate),2),LineTotal=i.LineTotal,Currency=q.Currency});order.StatusHistory.Add(new OrderStatusHistory{NewStatus=OrderStatus.PendingPayment,Reason="Převod přijaté nabídky"});db.Orders.Add(order);await db.SaveChangesAsync(ct);q.ConvertedOrderId=order.Id;q.Status=QuoteStatus.ConvertedToOrder;q.ProductInquiry.Status=InquiryStatus.ConvertedToOrder;q.StatusHistory.Add(new QuoteStatusHistory{PreviousStatus=QuoteStatus.Accepted,NewStatus=QuoteStatus.ConvertedToOrder,Reason="Převedeno na objednávku"});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return q;}
}
